import sys
from collections import deque

def ccw(A, B, C):
    return (C[1] - A[1]) * (B[0] - A[0]) > (B[1] - A[1]) * (C[0] - A[0])

def is_valid_turn(A, B, C, direction):
    return ccw(A, B, C) if direction == 'L' else not ccw(A, B, C)

def find_permutation(n, points, s):
    stack = deque()
    used = [False] * n
    result = []

    def dfs(prev, curr, index):
        if index == n - 1:
            result.append(curr + 1)
            return True
        result.append(curr + 1)
        used[curr] = True
        stack.append((prev, curr))
        for next_point in range(n):
            if not used[next_point] and (index == 0 or is_valid_turn(points[prev], points[curr], points[next_point], s[index - 1])):
                if dfs(curr, next_point, index + 1):
                    return True
        used[curr] = False
        stack.pop()
        result.pop()
        return False

    for start in range(n):
        if dfs(-1, start, 0):
            return result

    return -1

input = sys.stdin.read().strip().split('\n')
n = int(input[0])
points = [tuple(map(int, line.split())) for line in input[1:n+1]]
s = input[-1]

result = find_permutation(n, points, s)
if result == -1:
    print(-1)
else:
    print(' '.join(map(str, result)))
